package dev.pedro.learning.ecommerce.payment.provider;import jakarta.ws.rs.*;import jakarta.ws.rs.core.MediaType;@Path("/fake-payment-provider")@Consumes(MediaType.APPLICATION_JSON)@Produces(MediaType.APPLICATION_JSON)public class FakePaymentProviderResource{private final FakePaymentProviderState state;public FakePaymentProviderResource(FakePaymentProviderState state){this.state=state;}@POST @Path("/payments")public ProviderPaymentResponse pay(ProviderPaymentRequest request){return state.process(request);}}